const resumeToken = ($input.first().json.query && $input.first().json.query.token) ? $input.first().json.query.token : '';
const html = `<!DOCTYPE html><html lang="es"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Onboarding - ArquitAI</title>
<style>
  *{box-sizing:border-box}
  body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;padding:0;background:#f7f7f8;color:#222;height:100vh;display:flex;flex-direction:column}
  header{background:#fff;border-bottom:1px solid #e5e7eb;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;z-index:5}
  header h1{margin:0;font-size:16px;font-weight:600}
  header .meta{font-size:12px;color:#6b7280}
  .progress-bar{display:flex;gap:6px;align-items:center;margin-top:6px}
  .pill{font-size:10px;padding:3px 8px;border-radius:10px;background:#f3f4f6;color:#9ca3af}
  .pill.done{background:#d1fae5;color:#047857}
  main{flex:1;overflow-y:auto;padding:20px;max-width:780px;width:100%;margin:0 auto}
  .msg{margin-bottom:14px;display:flex}
  .msg.user{justify-content:flex-end}
  .bubble{max-width:80%;padding:10px 14px;border-radius:14px;font-size:14px;line-height:1.45;white-space:pre-wrap;word-wrap:break-word}
  .msg.assistant .bubble{background:#fff;border:1px solid #e5e7eb}
  .msg.user .bubble{background:#3b82f6;color:#fff}
  .typing{font-size:13px;color:#9ca3af;font-style:italic;padding:8px}
  footer{background:#fff;border-top:1px solid #e5e7eb;padding:12px 20px;position:sticky;bottom:0}
  .input-row{max-width:780px;margin:0 auto;display:flex;gap:8px}
  textarea{flex:1;border:1px solid #d1d5db;border-radius:8px;padding:10px 12px;font-family:inherit;font-size:14px;resize:none;min-height:44px;max-height:140px}
  button{background:#3b82f6;color:#fff;border:0;border-radius:8px;padding:0 18px;font-weight:600;cursor:pointer;font-size:14px;-webkit-tap-highlight-color:transparent}
  button:hover{background:#2563eb}
  button:disabled{background:#9ca3af;cursor:not-allowed}
  .empty-state{text-align:center;padding:40px 20px;color:#6b7280}
  .empty-state h2{margin:0 0 12px;font-size:20px;color:#1f2937}
  .empty-state p{margin:0 0 6px}
  .completed-banner{background:#d1fae5;border:1px solid #10b981;color:#047857;padding:14px;border-radius:8px;margin-bottom:14px}
</style>
</head>
<body>
<header>
  <div>
    <h1>Configuracion de tu estudio</h1>
    <div class="meta">Cuentame como trabajas y voy entendiendo tu estudio. Tarda 30-45 min.</div>
    <div class="progress-bar" id="progress">
      <span class="pill" data-section="identity">identidad</span>
      <span class="pill" data-section="tone">tono</span>
      <span class="pill" data-section="priorities">prioridades</span>
      <span class="pill" data-section="red_lines">líneas rojas</span>
      <span class="pill" data-section="visit_checklist">visita</span>
      <span class="pill" data-section="materials_pref">materiales</span>
      <span class="pill" data-section="trades_pref">gremios</span>
      <span class="pill" data-section="jurisdiction">jurisdiccion</span>
    </div>
  </div>
</header>
<main id="chat">
  <div class="empty-state" id="empty">
    <h2>Hola <span style="font-size:22px">👋</span></h2>
    <p>Soy el asistente de configuracion de ArquitAI.</p>
    <p>Voy a hacerte unas preguntas para personalizar el sistema a tu forma de trabajar.</p>
    <p style="margin-top:12px;color:#3b82f6">Escribe <strong>"empezar"</strong> abajo para arrancar.</p>
  </div>
</main>
<footer>
  <div class="input-row">
    <textarea id="input" placeholder="Escribe tu respuesta..." rows="1"></textarea>
    <button id="send">Enviar</button>
  </div>
</footer>
<script>
let API_KEY = window.localStorage.getItem('arquitai_api_key') || '';
if (!API_KEY) {
  API_KEY = prompt('Pega aqui tu x-api-key de ArquitAI (solo se pide la primera vez):') || '';
  if (API_KEY) window.localStorage.setItem('arquitai_api_key', API_KEY);
}
let resumeToken = ${JSON.stringify(resumeToken)};
const chat = document.getElementById('chat');
const empty = document.getElementById('empty');
const input = document.getElementById('input');
const sendBtn = document.getElementById('send');
const progressPills = document.querySelectorAll('#progress .pill');
let completed = false;

function addMessage(role, text) {
  if (empty.parentNode) empty.remove();
  const row = document.createElement('div');
  row.className = 'msg ' + role;
  const bubble = document.createElement('div');
  bubble.className = 'bubble';
  bubble.textContent = text;
  row.appendChild(bubble);
  chat.appendChild(row);
  chat.scrollTop = chat.scrollHeight;
  return row;
}
function setTyping(on) {
  let el = document.getElementById('typing');
  if (on && !el) {
    el = document.createElement('div');
    el.id = 'typing'; el.className = 'typing';
    el.textContent = 'escribiendo...';
    chat.appendChild(el); chat.scrollTop = chat.scrollHeight;
  } else if (!on && el) { el.remove(); }
}
function updateProgress(sectionsCovered) {
  progressPills.forEach(p => {
    const s = p.dataset.section;
    if (sectionsCovered && sectionsCovered[s]) p.classList.add('done');
    else p.classList.remove('done');
  });
}
function showCompleted() {
  if (completed) return; completed = true;
  const banner = document.createElement('div');
  banner.className = 'completed-banner';
  banner.innerHTML = '<strong>Onboarding completado.</strong> Tu perfil se esta guardando. Recibiras un email cuando todos los agentes esten personalizados con tu configuracion.';
  chat.appendChild(banner);
  input.disabled = true; sendBtn.disabled = true;
  chat.scrollTop = chat.scrollHeight;
}
async function send(text) {
  addMessage('user', text);
  input.value = ''; input.style.height = 'auto';
  input.disabled = true; sendBtn.disabled = true;
  setTyping(true);
  try {
    const r = await fetch('/webhook/setup-onboarding-message', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': API_KEY },
      body: JSON.stringify({ message: text, resume_token: resumeToken })
    });
    setTyping(false);
    if (!r.ok) {
      addMessage('assistant', 'Error: ' + r.status + '. Revisa tu API key (clear localStorage para resetear).');
      input.disabled = false; sendBtn.disabled = false;
      return;
    }
    const data = await r.json();
    if (data.resume_token) { resumeToken = data.resume_token; window.localStorage.setItem('arquitai_resume_token', resumeToken); }
    addMessage('assistant', data.message || '(respuesta vacia)');
    updateProgress(data.sections_covered);
    if (data.ready_to_close) showCompleted();
    else { input.disabled = false; sendBtn.disabled = false; input.focus(); }
  } catch (e) {
    setTyping(false);
    addMessage('assistant', 'Error de red: ' + e.message);
    input.disabled = false; sendBtn.disabled = false;
  }
}
sendBtn.addEventListener('click', () => { const t = input.value.trim(); if (t) send(t); });
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); const t = input.value.trim(); if (t) send(t); }
});
input.addEventListener('input', () => {
  input.style.height = 'auto'; input.style.height = Math.min(input.scrollHeight, 140) + 'px';
});
if (resumeToken) {
  const stored = window.localStorage.getItem('arquitai_resume_token');
  if (stored && stored === resumeToken) addMessage('assistant', 'Reanudando tu sesion anterior...');
}
input.focus();
</script>
</body></html>`;
return [{ json: { html } }];
